INSERT INTO `b2c_meta_tags` (`entry_id`, `page`, `title`, `descriiption`, `keywords`) VALUES
(1, 'index', 'Best Travel Agency for Holiday Packages, Tours & Vacations', 'Discover exciting holiday packages, customized tours, honeymoon trips, family vacations, group tours, and international travel packages at affordable prices.', 'travel agency, holiday packages, tour packages, vacation packages, family holidays, honeymoon packages, international tours, domestic tours, travel planner'),
(2, 'about', 'About Our Travel Services | Trusted Tour & Travel Experts', 'Learn about our travel expertise, customized tour planning, professional travel assistance, and commitment to creating unforgettable travel experiences.', 'about travel agency, travel experts, tour operator, travel planner, holiday experts, customized travel'),
(3, 'package', 'Domestic Tour Packages Across India', 'Explore the best domestic holiday destinations including Kashmir, Goa, Kerala, Himachal, Rajasthan, Andaman, Ladakh, and more.', 'domestic tour packages, India holidays, Kashmir tour, Goa package, Kerala trip, Himachal tour, Rajasthan holiday'),
(4, 'group', 'Group Tour Packages & Customized Group Trips', 'Plan exciting group vacations with friends, corporate teams, schools, and organizations through professionally managed group tours.', 'group tours, corporate tours, school tours, friends trip, group holiday packages'),
(5, 'blog', 'Travel Blog, Tips & Destination Guides', 'Read travel tips, destination guides, packing advice, travel inspiration, and expert recommendations for your next holiday.', 'travel blog, travel tips, destination guide, holiday ideas, travel inspiration'),
(6, 'gallary_new', 'Travel Photo Gallery & Holiday Memories', 'Browse beautiful travel photographs showcasing destinations, adventures, beaches, mountains, and memorable travel experiences.', 'travel gallery, holiday photos, destination images, vacation gallery'),
(7, 'testimonials', 'Customer Reviews & Travel Experiences', 'Read genuine customer reviews and travel stories shared by families, couples, friends, and corporate travelers.', 'customer reviews, travel testimonials, holiday experiences, travel feedback'),
(8, 'contact', 'Contact Travel Experts for Tour Packages', 'Get in touch with our travel experts for customized holiday packages, travel planning, bookings, and support.', 'contact travel agency, travel enquiry, holiday booking, travel consultant'),
(9, 'privacy-policy', 'Read our privacy policy to understand how we collect, use, store, and protect your personal information', 'privacy policy, data protection, customer privacy, travel website policy', 'privacy policy, data protection, customer privacy, travel website policy'),
(10, 'refund-policy', 'Refund & Cancellation Policy', 'Learn about our refund process, cancellation policy, booking terms, and refund timelines for travel services.', 'refund policy, cancellation policy, travel refund, booking cancellation'),
(11, 'terms', 'Terms & Conditions for Travel Services', 'Review the terms and conditions governing bookings, payments, cancellations, and the use of our travel website and services.', 'terms and conditions, travel terms, booking policy, website terms'),
(12, 'activities', 'Adventure Activities & Travel Experiences', 'Discover exciting travel activities including sightseeing, adventure sports, wildlife safaris, cultural tours, water sports, trekking, and unique local experiences for every traveler.', 'travel activities, adventure tours, sightseeing, water sports, trekking, safari, cultural tours, travel experiences, things to do'),
(13, 'Visa', 'Visa Assistance for International Travel', 'Get reliable visa assistance for tourist, business, and holiday travel. Our experts help simplify the visa application process for multiple destinations worldwide.', 'visa services, tourist visa, travel visa, visa assistance, international visa, visa documentation, visa application'),
(14, 'Car Rental', 'Airport Transfers & Local Transportation Services', 'Book reliable airport transfers, private cabs, intercity transfers, hotel pickups, and comfortable transportation for a smooth travel experience.', 'airport transfer, hotel transfer, cab booking, local transport, private transfer, travel transportation, airport pickup'),
(15, 'Cruise', 'Luxury Cruise Holidays & Cruise Packages', 'Experience unforgettable cruise vacations with premium accommodations, onboard entertainment, dining, and exciting destinations across the world.', 'cruise packages, luxury cruise, cruise holidays, ocean cruise, river cruise, cruise vacation, international cruise'),
(16, 'services', 'Complete Travel Services & Holiday Solutions', 'Explore our comprehensive travel services including holiday planning, hotel bookings, flight reservations, visa assistance, transportation, cruises, and customized tour packages.', 'travel services, holiday planning, hotel booking, flight booking, visa services, customized tours, travel solutions'),
(17, 'award', 'Awards & Recognition', 'Discover our achievements, industry recognition, certifications, and milestones that reflect our commitment to delivering exceptional travel experiences.', 'travel awards, achievements, recognition, travel excellence, tourism awards, certifications'),
(18, 'career', 'Careers in Travel & Tourism', 'Join our growing team and build your career in the travel and tourism industry. Explore exciting job opportunities and professional growth.', 'travel jobs, tourism careers, job openings, travel company careers, employment opportunities, tourism jobs'),
(19, 'Offers', 'Exclusive Holiday Deals & Travel Offers', 'Save more with special travel deals, seasonal discounts, honeymoon offers, family holiday packages, group tour promotions, and limited-time travel discounts.', 'travel offers, holiday deals, tour discounts, honeymoon offers, family package deals, travel promotions, special offers');
