INSERT INTO `b2c_testimonials` (`entry_id`, `name`, `designation`, `testm`, `image`) VALUES
(1, 'Mr. Priya Sharma', 'Family Traveler', '\"We booked our family vacation through this tour operator, and everything was perfectly organizedâ€”from hotels and sightseeing to airport transfers. The team was always available to help, making our trip completely stress-free.', '../../../images/testimonial/2026/Jul/01/1782896111/Untitled-3.png'),
(2, 'Mr. Rahul Mehta', 'Friends Group', '\"Planning a trip for a group of friends is never easy, but the entire experience was seamless. The itinerary was well balanced with adventure, relaxation, and nightlife.', '../../../images/testimonial/2026/Jul/01/1782896124/Untitled-2.png'),
(3, 'Neha Kapoor', 'HR Manager', '\"We organized our company\'s annual offsite through this team, and they exceeded our expectations. From accommodation and transportation to conference arrangements and team-building activities, everything was professionally managed.', '../../../images/testimonial/2026/Jul/01/1782896176/Untitled-1.png'),
(4, 'Aarav & Sneha Joshi', 'Newly Married Couple', '\"Our honeymoon was absolutely magical thanks to the thoughtful planning and personalized service. Every hotel, activity, and surprise recommendation made our journey extra special.', '../../../images/testimonial/2026/Jul/01/1782896159/Untitled-4.png');
