INSERT INTO `custom_package_offers` (`entry_id`, `package_id`, `type`, `from_date`, `to_date`, `offer_in`, `coupon_code`, `offer_amount`, `agent_type`) VALUES
(1, 31, 'Offer', '2026-07-20', '2026-07-31', 'Flat', '', 1000.00, 'Platinum,Gold,Silver');
INSERT INTO `custom_package_program` (`entry_id`, `package_id`, `day_no`, `attraction`, `day_wise_program`, `stay`, `meal_plan`, `day_image`) VALUES
(1, 1, 1, 'Arrival at Cochi', 'Welcome to your Kochi. Upon arrival at the Kochi international airport start on your journey to the hotel in Kochi.  Once you reach Kochi Hotel, complete the check-in formalities at the hotel.', 'Cochin', '', ''),
(2, 1, 2, 'Travel from Kochi - Munnar', 'After delicious breakfast, check out from the hotel and Set out on a sightseeing tour in Kochi. Later in Afternoon driver to Munnar. Munnar is a beautiful hill town which is located in the Western Ghats. The place is full of rolling hills, stunning tea plantations, spice plantations and much more. It is the ideal holiday destination to unwind all your stress. Enroute visit Cheeyappara Waterfall and Valara Waterfalls. Upon your arrival in Munnar, check into your hotel and then unwind youself. Rest of the day is at Leisure.', 'Munnar', '', ''),
(3, 1, 3, 'Travel from Munnar - Thekkady', 'Relish the lip-smacking breakfast at the hotel, check-out and we will drive you to a next highly picturesque destination Thekkady. Enroute visit Spice Plantation. On arrival, check-in at the hotel and relax for some time. Later walk on the street on Thekkady and visit Epephant Junction to enjoy Elephant Ride and watch Elephant Bathing. Later In evening be mesmerized by a live show of Kalaripayattu. After a joyfull day return back to hotel for dinner.', 'Thekkady', '', ''),
(4, 1, 4, 'Travel Thekkady Alleppey & Departure', 'After breakfast, check out of the hotel. Drive to Alleppey and transfer to airport/railway station for your onward journey.', 'Tour End', '', ''),
(5, 2, 1, 'Arrival at Cochi', 'Welcome to your Kochi. Upon arrival at the Kochi international airport start on your journey to the hotel in Kochi.  Once you reach Kochi Hotel, complete the check-in formalities at the hotel.', 'Cochi', '', NULL),
(6, 2, 2, 'Travel from Kochi - Munnar', 'After delicious breakfast, check out from the hotel and Set out on a sightseeing tour in Kochi. Later in Afternoon driver to Munnar. Munnar is a beautiful hill town which is located in the Western Ghats. The place is full of rolling hills, stunning tea plantations, spice plantations and much more. It is the ideal holiday destination to unwind all your stress. Enroute visit Cheeyappara Waterfall and Valara Waterfalls. Upon your arrival in Munnar, check into your hotel and then unwind youself. Rest of the day is at Leisure.', 'Munnar', '', NULL),
(7, 2, 3, 'Munnar Local Sightseeing', 'After breakfast, take a sightseeing tour of Munnar visiting the Eravikulam National Park, Mattupetty Dam, Old Munnar Town and the town market. Enjoy rest of the day at leisure. ', 'Munnar', '', NULL),
(8, 2, 4, 'Travel Thekkady- Alleppey & Departure', 'After breakfast, check out of the hotel. Drive to Alleppey and transfer to airport/railway station for your onward journey.', 'Tour End', '', NULL),
(9, 3, 1, 'Arrival at Port Blair', 'Arrive at Port Blair and you will be taken to your hotel where you relax and rest and after lunch proceed for local sightseeing of Port Blair. Later you will be taken to Cellular Jail (closed on Mondays) to enjoy beautiful Light and Sound show. Evening is free for leisure activities.', 'Port Blair', '', NULL),
(10, 3, 2, 'Port Blair to Havelock', 'Morning we go to Corbyns Cove Beach the most active beach side of Port Blair. We start our journey towards Havelock Island via ferry from Port Blair Harbor. On arrival at Havelock Island, our representative will receive and escort you to check-in to the resort. After relax, day free for own leisure at Havelock Island.', 'Havelock', '', NULL),
(11, 3, 3, 'Havelock - Neil Island', 'After buffet breakfast, check out from the hotel. Transfer to the Havelock jetty to board the ferry for Neil Island. Post lunch (on direct payment), proceed to visit Bharatpur beach, Laxmanpur beach and Howrah Bridge (depending on tide conditions).  Return to the hotel in the evening. Enjoy your dinner and a comfortable overnight stay at the hotel.', 'Neil Island', '', NULL),
(12, 3, 4, 'Neil Island-Port Blair', 'This morning after breakfast you will transfer to Port Blair airport in time to board your flight. Depart Port Blair with fond memories of these mesmerizing Islands.', 'aa', '', NULL),
(13, 4, 1, 'Arrival at Port Blair', 'Arrive at Port Blair and you will be taken to your hotel where you relax and rest and after lunch proceed for local sightseeing of Port Blair. Later you will be taken to Cellular Jail (closed on Mondays) to enjoy beautiful Light and Sound show. Evening is free for leisure activities.', 'Port Blair', '', NULL),
(14, 4, 2, 'Port Blair to Havelock', 'Morning we go to Corbyns Cove Beach the most active beach side of Port Blair. We start our journey towards Havelock Island via ferry from Port Blair Harbor. On arrival at Havelock Island, our representative will receive and escort you to check-in to the resort. After relax, day free for own leisure at Havelock Island.', 'Havelock', '', NULL),
(15, 4, 3, 'Havelock - Radhanagar Beach and Kalapathar Beach', 'After breakfast day free for own leisure, afternoon we proceed to Radhanagar Beach, the Times Magazine rated the finest beach among the best beaches in Asia. It is an ideal place for swimming, sea bathing and basking on the sun kissed beaches. Later Visit the Kalapathar Beach for its blue waters.', 'Havelock', '', NULL),
(16, 4, 4, 'Havelock - Neil Island', 'After buffet breakfast, check out from the hotel. Transfer to the Havelock jetty to board the ferry for Neil Island. Post lunch (on direct payment), proceed to visit Bharatpur beach, Laxmanpur beach and Howrah Bridge (depending on tide conditions).  Return to the hotel in the evening. Enjoy your dinner and a comfortable overnight stay at the hotel.', 'Neil Island', '', NULL),
(17, 4, 5, 'Neil Island- Port Blair', 'This morning after breakfast you will transfer to Port Blair airport in time to board your flight. Depart Port Blair with fond memories of these mesmerizing Islands.', 'Tour End', '', NULL),
(18, 5, 1, 'Arrive Goa', 'Transfer from Goa Airport/Thivim Railway Station to Hotel', 'Goa', '', NULL),
(19, 5, 2, 'In Goa', 'Day at Leisure.', 'Goa', '', NULL),
(20, 5, 3, 'In Goa', 'Day at Leisure', 'Goa', '', NULL),
(21, 5, 4, 'Transfer to Airport/ Railway station.', 'Transfer from Hotel to Goa Airport/Thivim Railway Station.', 'Tour End', '', NULL),
(22, 6, 1, 'Arrive Goa', 'Transfer from Goa Airport/Thivim Railway Station to Hotel', 'Goa', '', NULL),
(23, 6, 2, 'In Goa', 'Day at Leisure.', 'Goa', '', NULL),
(24, 6, 3, 'In Goa', 'Day at Leisure', 'Goa', '', NULL),
(25, 6, 4, 'In Goa', 'Day at Leisure', 'Goa', '', NULL),
(26, 6, 5, 'Travel to Airport', 'Transfer from Hotel to Goa Airport/Thivim Railway Station.', 'Tour End', '', NULL),
(27, 7, 1, 'Ahmedabad / Rajkot ï¿½ Jamnagar ï¿½ Dwarka', 'Morning after breakfast proceeds to Dwarka, en-route visit Jamnagar Bala Hanuman Temple - Bala Hanuman Temple is a pilgrim place venerated by the devotees of Lord Ram. It is a world famous temple, known for the continuous chanting of Jai Ram, Shri Ram. The chanting is going on since 1964 and has found a place for it in the Guinness Book of World Records. People chant the name of the Lord in shifts, 24 hours a day. Later Proceed to Dwarka, visit Lords Dwarkadhish Temple. Attend evening Aarti Darshan at Dwarkadhish.', 'Dwarka', '', NULL),
(28, 7, 2, 'Dwarka', 'Attend early morning Aarti at Dwarkadhish temple, have breakfast & thereafter visit Bet Dwarka, Nageshwar Jyotirling & Rukmani Temple.\n\nVisit Nageswar Mahadev & Rukmani Temple. Back to the Hotel', 'Dwarka', '', NULL),
(29, 7, 3, 'Dwarka-Porbandar ï¿½ Somnath', 'Morning after breakfast proceeds to Porbandar, visit Kirti temple, Sudam known as house & born place of Mahatma Gandhi. In back side house of Kasturba wife of Gandhi. Also visit of Gandhi museum, study room of Mahatma Gandhi in the Kirti temple.\n\nLater visit of Sudama temple & continue proceed to Somnath, evening aarti Darshan at Somnath Temple', 'Somnath', '', NULL),
(30, 7, 4, 'Somnath-Ahmedabad Departure', 'Morning after early Breakfast proceeds to Ahmedabad and transfer to airport / railway station for onward journey', 'Tour End', '', NULL),
(31, 8, 1, 'Arrives at Ahmedabad', 'Arrival at Ahmadabad, Meet to Greet visit Akshardham Temple (Monday Closed) Akshardham is situated in the capital city of Gandhinagar, which lies near Ahmadabad.\n\nLater drive to Adalaj, visit step well is an architectural wonder built by Queen Rudabai and is certainly one of the finest monuments of Gujarat.', 'Ahmedabad', '', NULL),
(32, 8, 2, 'Ahmedabad-amnagar ï¿½ Dwakra', 'Morning after breakfast drive to Dwarka, en-route visit Jamnagar Bala Hanuman Temple - Bala Hanuman Temple is a pilgrim place venerated by the devotees of Lord Ram.\n\nLater Proceed to Dwarka, visit Lords Dwarkadhish Temple. Attend evening Aarti Darshan at Dwarkadhish Temple ï¿½ Temple of Lord Krishna.', 'Dwarka', '', NULL),
(33, 8, 3, 'Dwarka-Porbandar ï¿½ Somnath', 'Morning proceed to Porabandar, Visit Kirti temple, Sudam known as house & born place of Mahatma Gandhi. In back side house of Kasturba wife of Gandhi. Also visit of Gandhi museum, study room of Mahatma Gandhi in the Kirti\n\ntemple. Later visit of Sudama temple & continue proceed to Somnath, evening Aarti Darshan at Somnath Temple - A lord', 'Somnath', '', NULL),
(34, 8, 4, 'Somnath-Diu', 'Morning after breakfast visit Bhalika Tirth & Triveni Ghat. Later drive to Diu, visit Diu: A beautiful blend of sun, sand and sea, Diu is a Gods gift to those in quest of a blessed land where the weary weight of this unintelligible world can, for a while, be lightened and the waking soul can hear the music of the nature. ', 'Dui', '', NULL),
(35, 8, 5, 'Somnath-Ahmedabad Departure', 'Morning after breakfast drive to Ahmedabad and transfer to Airport /Railway station for onward journey.', 'Tour End', '', NULL),
(36, 9, 1, 'Arrival Chandigarh', 'Welcome onboard a wonderful tour to one of the most happening destinations - Himachal!\n\nArrival at the Chandigarh Airport. Complimentary Transfer from Airport to the Regenta Central Cassia  Amritsar at 1200 Hrs. \nwe start Chandigarh City Tour visit Sukhna Lake, Rock Garden, Elante Mall, and the local Punjabi food of Chandigarh', 'Chandigarh', '', NULL),
(37, 9, 2, 'Chandigarh To Manali', 'After an early breakfast, depart for Manali by road.  Manali is a high-altitude Himalayan resort town in Indias northern Himachal Pradesh state. It has a reputation as a backpacking centre and honeymoon destination. Set on the Beas River, it\'s a gateway for skiing in the Solang Valley and trekking in Parvati Valley. It\'s also a jumping-off point for paragliding, rafting and mountaineering in the Pir Panjal mountains , Arrive Manali check in at the hotel.', 'Manali', '', NULL),
(38, 9, 3, 'Manali To Shimla', 'After an early breakfast, depart for Shimla by road. Shimla The town is famous for pleasant walking experiences on hillsides surrounded by pine and oak forests. This capital city of Himachal Pradesh is famous for The Mall, ridge, and toy train. With colonial style buildings, the town has relics of ancient past that lend it a distinct look.  Arrive shimla check in hotel and overnight at Resorts.', 'Shimla', '', NULL),
(39, 9, 4, 'Chandigarh Departure', 'Today after early breakfast, proceed to Chandigarh Airport at. Arrive Airport drop at airport for onward journey.', 'Tour End', '', NULL),
(40, 10, 1, 'Arrival Chandigarh', 'Welcome onboard a wonderful tour to one of the most happening destinations - Himachal!\n\nArrival at the Chandigarh Airport. Complimentary Transfer from Airport to the Regenta Central Cassia  Amritsar at 1200 Hrs. \nwe start Chandigarh City Tour visit Sukhna Lake, Rock Garden, Elante Mall, and the local Punjabi food of Chandigarh', 'Chandigarh', '', NULL),
(41, 10, 2, 'Chandigarh To Manali', 'After an early breakfast, depart for Manali by road.  Manali is a high-altitude Himalayan resort town in Indias northern Himachal Pradesh state. It has a reputation as a backpacking centre and honeymoon destination. Set on the Beas River, it\'s a gateway for skiing in the Solang Valley and trekking in Parvati Valley. It\'s also a jumping-off point for paragliding, rafting and mountaineering in the Pir Panjal mountains , Arrive Manali check in at the hotel.', 'Manali', '', NULL),
(42, 10, 3, 'Manali To Shimla', 'After an early breakfast, depart for Shimla by road. Shimla The town is famous for pleasant walking experiences on hillsides surrounded by pine and oak forests. This capital city of Himachal Pradesh is famous for The Mall, ridge, and toy train. With colonial style buildings, the town has relics of ancient past that lend it a distinct look.  Arrive shimla check in hotel and overnight at Resorts.', 'Shimla', '', NULL),
(43, 10, 4, 'Shimla Tour', 'After breakfast Drive to Kufri derives its name from Kufri which means lake. It is especially popular among trekkers. The salubrious climate and stunning natural beauty makes Kufri a perfect summer getaway. Kufri is also a haven for nature enthusiasts and wildlife lovers as the Himalayan Nature Park is situated on the outskirts of the town. Thereafter visit Shimla followed by Indira Bungalow and Himalayan Zoo. Later we stroll on the famous Mall Road to we view Christ Church, Scandal Point, The Ridge. After visit back to resort and relax. Over-night at the resort.', 'Shimla', '', NULL),
(44, 10, 5, 'Chandigarh Departure', 'Today after early breakfast, proceed to Chandigarh Airport at. Arrive Airport drop at airport for onward journey.', 'Tour End', '', NULL),
(45, 11, 1, 'Arrive Srinagar', 'Arrival at Srinagar Airport. The vehicle to the hotel departs from Srinagar Airport. Guests are requested to time their flights as per this schedule to avail the complimentary transfers or else they may opt for the add-on transfers on extra payment basis. Reach your hotel. Check in and freshen up. In Evening Enjoy Shikara ride on Dal Lake.', 'Srinagar', '', NULL),
(46, 11, 2, 'Srinagar- Pahalgam', 'Today after an early breakfast Visit Shankaracharya Temple situated on top of the Shankaracharya Hill on the Zabarwan Range in Srinagar, Jammu and Kashmir, India.\n\nArrive Pahalgam and transfer to your hotel. Rest of the day is at leisure.', 'Pahalgam', '', NULL),
(47, 11, 3, 'Pahalgam - Gulmarg', 'Today after breakfast enjoy a picturesque drive to Gulmarg. You may enjoy an optional sledge ride or Cable car ride on the snow covered slopes (on direct payment basis)', 'Gulmarg', '', NULL),
(48, 11, 4, 'Gulmarg - Srinagar', 'After breakfast You Can Enjoy Gulmarg Gondola , Asia\'s largest and highest and world\'s second-largest and second highest cable car project, Gulmarg Gondola is the top attraction in Gulmarg. In fact, a Gulmarg tour without a ride on the popular cable car is considered incomplete.', 'Tour End', '', NULL),
(49, 12, 1, 'Arrive Srinagar', 'Arrival at Srinagar Airport. The vehicle to the hotel departs from Srinagar Airport. Guests are requested to time their flights as per this schedule to avail the complimentary transfers or else they may opt for the add-on transfers on extra payment basis. Reach your hotel. Check in and freshen up. In Evening Enjoy Shikara ride on Dal Lake.', 'Srinagar', '', NULL),
(50, 12, 2, 'Srinagar- Pahalgam', 'Today after an early breakfast Visit Shankaracharya Temple situated on top of the Shankaracharya Hill on the Zabarwan Range in Srinagar, Jammu and Kashmir, India.\n\nArrive Pahalgam and transfer to your hotel. Rest of the day is at leisure.', 'Pahalgam', '', NULL),
(51, 12, 3, 'Pahalgam-Gulmarg', 'Today after breakfast enjoy a picturesque drive to Gulmarg. You may enjoy an optional sledge ride or Cable car ride on the snow covered slopes (on direct payment basis)', 'Gulmarg', '', NULL),
(52, 12, 4, 'Gulmarg Local sightseeing', 'After breakfast, proceed for Skiing. Gulmarg is having one of the best skiing slops in world and its famous for amateur as well as advance skiing. One can also opt for a fun-filled pony ride and gondola rides (on direct payment). Evening is free for leisure activities.', 'Gulmarg', '', NULL),
(53, 12, 5, 'Gulmarg - Srinagar', 'After breakfast You Can Enjoy Gulmarg Gondola , Asia\'s largest and highest and world\'s second-largest and second highest cable car project, Gulmarg Gondola is the top attraction in Gulmarg. In fact, a Gulmarg tour without a ride on the popular cable car is considered incomplete.', 'Tour End', '', NULL),
(54, 13, 1, 'Arrival at Jaipur', 'Upon arrival at Jaipur (also known as Pink City), check in at the hotel and relax. Later in the afternoon, proceed to visit the City Palac, Shri Govind Deo Temple. En-route, visit the Hawa Mahal. We will also visit Jantar Mantar, a stone observatory, which is the largest of Jai Singh\'s five remarkable observatories.', 'Jaipur', '', NULL),
(55, 13, 2, 'Jaipur-Jodhpur', 'Early breakfast, check out from the Hotel & drive to Jodhpur (also known as Blue City). En-route visit to Pushkar. Arrival Jodhpur & check in hotel. Spend the evening at leisure. Dinner and overnight stay at the hotel.', 'Jodhpur', '', NULL),
(56, 13, 3, 'Jodhpur-Udaipur', 'After breakfast, check out from the Hotel & drive to Udaipur in the morning. Check in and overnight stay at the hotel in Udaipur, the City of Lakes.', 'Udaipur', '', NULL),
(57, 13, 4, 'Departure Udaipur', 'Today after breakfast, check out of the hotel and you are transferred to the Udaipur airport or railway station for your onward journey.', 'Tour End', '', NULL),
(58, 14, 1, 'Arrival at Jaipur', 'Upon arrival at Jaipur (also known as Pink City), check in at the hotel and relax. Later in the afternoon, proceed to visit the City Palac, Shri Govind Deo Temple. En-route, visit the Hawa Mahal. We will also visit Jantar Mantar, a stone observatory, which is the largest of Jai Singh\'s five remarkable observatories.', 'Jaipur', '', NULL),
(59, 14, 2, 'Jaipur-Jodhpur', 'Early breakfast, check out from the Hotel & drive to Jodhpur (also known as Blue City). En-route visit to Pushkar. Arrival Jodhpur & check in hotel. Spend the evening at leisure. Dinner and overnight stay at the hotel.', 'Jodhpur', '', NULL),
(60, 14, 3, 'Jodhpur - Udaipur', 'After breakfast, check out from the Hotel & drive to Udaipur in the morning. Check in and overnight stay at the hotel in Udaipur, the City of Lakes.', 'Udaipur', '', NULL),
(61, 14, 4, 'Jodhpur City tour- Osian', 'After breakfast local city sightseeing tour Jodhpur, stronghold of the fierce Rathore clan, was founded in 1459 by Prince Jodha. Visit the Mehrangarh Fort, situated on a low sandstone hill. Within the fort, visit Moti Mahal and Phool Mahal. Also visit Jaswant Thada, an imposing marble cenotaph, built in memory of Maharaja Jaswant singh II around 1899 and afternoon visit to Umaid Bhawan Palace and evening enjoy leisure time at Umaid Public gardens & Mandore Garden. Later drive to Osian on arrival check in at the Tents, after that enjoy Camel rider at nearby Sand Dunes and Evening Return back to Return back to Resort for Dinner & overnight stay.', 'Osian', '', NULL),
(62, 14, 5, 'Osian-Udaipur', 'Today after breakfast, check out of the hotel and you are transferred to the Udaipur airport or railway station for your onward journey.', 'Tour End', '', NULL),
(63, 15, 1, 'Arrival in Bali', 'Arrive in Bali upon arrival at the Ngurah Rai, Bali International Airport, meet & greet by our local guide who lead you to the parking area to board on vehicle for your transfer to your hotel.\n\nUpon arrival at the hotel, directly check in and freshen up.', 'Bali', '', NULL),
(64, 15, 2, 'Tanah Lot Tour', 'Breakfast at the hotel\n\nIn the afternoon, proceed for Tanah Lot Floating Temple as your first itinerary in this trip. This temple is very beautiful in the particular of the sunset time. We can view this temple from several spot points with spectacular view of the ocean and sunset. The word of Tanah Lot is consisted of two words that are Tanah word interpreted as a reef looking like gili or island. Lot or Lod word has meaning the sea. So Tanah Lot is meaning the small island floating on the sea.  Transfer back to hotel for overnight', 'Bali', '', NULL),
(65, 15, 3, 'Full Day Kintamani Tour with Ubud', 'Breakfast at hotel\n\nWe pick up from your hotel, and start the tour program by visiting the Tegenungan Waterfall. Waterfall located right in the southern area of the island.\n\nWe continue to visit Kintamani Village to see Mt Batur. Kintamani is a district. Then we then continue to visit Ubud Monkey Forest.', 'Bali', '', NULL),
(66, 15, 4, 'Departure', 'Breakfast at hotel\n\nPick up from the hotel to transfer to the Airport according to the scheduled Flight.', 'Tour End', '', NULL),
(67, 16, 1, 'Arrival-Tanah Lot Tour', 'Upon arrival in Bali at the Ngurah Rai, Bali International Airport, meet & greet by our local guide who will assist you to board a vehicle for your transfer to your hotel.\n\nTransfer back to hotel for overnight', 'Bali', '', NULL),
(68, 16, 2, 'Full Day: Ubud & Kintamani Tour', 'Breakfast at hotel. We pick up from your hotel, and start the tour program by visiting Batuan Temple. Batuan Temple, referred to locally as Pura Puseh lan Pura Desa Adat Batuan.\n\nWe are then continue to visit Silver Village Celuk.\n\nThe Last stop will be Bali Ubud Royal Palace & Ubud Art Market.', 'Bali', '', NULL),
(69, 16, 3, 'Today the day is free at leisure', 'Overnight at the hotel', 'Bali', '', NULL),
(70, 16, 4, 'Today the day is free at leisure', 'Overnight at the hotel', 'Bali', '', NULL),
(71, 16, 5, 'Departure', 'Breakfast at hotel. Pick up from the hotel to transfer to the Airport according to the scheduled Flight', 'Tour End', '', NULL),
(72, 17, 1, 'Arrive Male', 'Upon arrival in Male, you will be transferred to your resort. Check in at the hotel. Enjoy the rest of the day at leisure.\n\nOvernight at the resort', 'Male', '', NULL),
(73, 17, 2, 'Male', 'Enjoy breakfast at the hotel. Later enjoy your day at leisure, explore the island on your own\n\nOvernight at the resort', 'Male', '', NULL),
(74, 17, 3, 'Male', 'Enjoy breakfast at the hotel. Later enjoy your day at leisure, explore the island on your own\n\nOvernight at the resort', 'Male', '', NULL),
(75, 17, 4, 'Depart Male', 'After breakfast, check out (standard 1200 hrs) and transfer from the hotel to International Airport for the departure flight back to India or to your onwards destination.', 'Tour End', '', NULL),
(76, 18, 1, 'Arrive Male', 'Upon arrival in Male, you will be transferred to your resort. Check in at the hotel. Enjoy the rest of the day at leisure.\n\nOvernight at the resort', 'Male', '', NULL),
(77, 18, 2, 'Male', 'Enjoy breakfast at the hotel. Later enjoy your day at leisure, explore the island on your own\n\nOvernight at the resort', 'Male', '', NULL),
(78, 18, 3, 'Male', 'Enjoy breakfast at the hotel. Later enjoy your day at leisure, explore the island on your own\n\nOvernight at the resort', 'Male', '', NULL),
(79, 18, 4, 'Male', 'Enjoy breakfast at the hotel. Later enjoy your day at leisure, explore the island on your own\n\nOvernight at the resort', 'Male', '', NULL),
(80, 18, 5, 'Depart Male', 'After breakfast, check out (standard 1200 hrs) and transfer from the hotel to International Airport for the departure flight back to India or to your onwards destination.', 'Tour End', '', NULL),
(89, 21, 1, 'Arrive Singapore : Day at Leisure', 'Welcome to Singapore! Upon arrival at Singapore Airport, transfer to the Hotel & check in. The island of Singapore gives you a panoramic view of paradise, you will find the atmosphere of Singapore calming yet exotic making it a persuasive combination of all one would want in a place to reside in.', 'Singapore', '', NULL),
(90, 21, 2, 'Singapore: Sentosa tour', 'Post breakfast, around proceed to Sentosa - Singapore\'s good-time island dedicated to unabashed fun, fake surf and cool beach bars. Enjoy the 02 way cable car ride, Madame Tussauds 4 in1 including Ultimate Film Star Experience & Wings Of Time Show.\n\nIn the evening enjoy Wings of Time  and then transfer back to the hotel', 'Singapore', '', NULL),
(91, 21, 3, 'Singapore Half Day City Tour', 'This morning we proceed on a half day city tour of Singapore . Discover the history, culture and lifestyle of multi racial Singapore in this Tour. The tour begins with a drive around the Civic District past  Suntec City, City Hall, & Fountain of Wealth (The Fountain of Wealth is listed by the Guinness Book of Records in 1998 as the largest fountain in the world ) Stop at the Merlion Park which is located near Marina Bay, Singapore.\n\nReturn back to the hotel', 'Singapore', '', NULL),
(92, 21, 4, 'Depart Singapore', 'This morning after breakfast, you will be transferred to the airport for your onward flight home.', 'Tour End', '', NULL),
(93, 22, 1, 'Arrive Singapore : Day at Leisure', 'Welcome to Singapore! Upon arrival at Singapore Airport, transfer to the Hotel & check in. The island of Singapore gives you a panoramic view of paradise, you will find the atmosphere of Singapore calming yet exotic making it a persuasive combination of all one would want in a place to reside in.', 'Singapore', '', NULL),
(94, 22, 2, 'Singapore: Sentosa tour', 'Post breakfast, around proceed to Sentosa - Singapore\'s good-time island dedicated to unabashed fun, fake surf and cool beach bars. Enjoy the 02 way cable car ride, Madame Tussauds 4 in1 including Ultimate Film Star Experience & Wings Of Time Show.\n\nIn the evening enjoy Wings of Time  and then transfer back to the hotel', 'Singapore', '', NULL),
(95, 22, 3, 'Singapore Half Day City Tour', 'This morning we proceed on a half day city tour of Singapore . Discover the history, culture and lifestyle of multi racial Singapore in this Tour. The tour begins with a drive around the Civic District past  Suntec City, City Hall, & Fountain of Wealth (The Fountain of Wealth is listed by the Guinness Book of Records in 1998 as the largest fountain in the world ) Stop at the Merlion Park which is located near Marina Bay, Singapore.\n\nReturn back to the hotel', 'Singapore', '', NULL),
(96, 22, 4, 'Day at leisure', 'Enjoy a leisurely breakfast. The day is free to relax or choose from one of the suggested optional tours.\n\nOvernight: Hotel in Singapore', 'Singapore', '', NULL),
(97, 22, 5, 'Depart Singapore', 'This morning after breakfast, you will be transferred to the airport for your onward flight home.', 'Tour End', '', NULL),
(98, 23, 1, 'Arrive DubaiTime at Leisure', 'On arrival at Dubai International Airport, you\'ll be transferred to your hotel. Upon arrival check in to the hotel and relax. ', 'Dubai', '', ''),
(99, 23, 2, 'Dubai: Morning at Leisure; Evening Dhow Cruise with Dinner', 'Enjoy breakfast at the hotel.\n\nIn the evening get ready to experience the Dhow Cruise. Cruising down Dubai creek is a novel experience, one which you cannot miss when in Dubai. Having fancy dinner on a Dhow Cruise with the fascinating lights of Dubai Creek and the soft music in the background, sip your favorite drink and enjoy a buffet dinner on board the cruise.', 'Dubai', '', ''),
(100, 23, 3, 'Dubai Half Day City Tour  Followed By At the Top Burj Khalifa', 'After breakfast, proceed for a half day morning city tour, viewing some of the city most beautiful landmarks. The Magnificent Jumeriah Mosque built in 1979 is a fine example of modern Islamic architecture.\n\nYouï¿½ll be dropped back to Dubai Mall. You can use this time to have your lunch\n\nTake a closer look at the world below through avant-garde, high powered, telescopes. Step out onto the world\'s highest public outdoor observation terrace overlooking the ever growing skyline of Sheikh Zayed Road and surrounding panorama.\n\nReturn to hotel for a comfortable overnight stay.', 'Dubai', '', ''),
(101, 23, 4, 'Dubai Departure', 'Today enjoy breakfast at the hotel. Later check out and Transfer to Dubai airport for your departure flight. We hope you take back many happy memories of your holiday.', 'Tour End', '', ''),
(102, 24, 1, 'Arrive Dubai Time at Leisure', 'On arrival at Dubai International Airport, you\'ll be transferred to your hotel. Upon arrival check in to the hotel and relax. ', 'Dubai', '', NULL),
(103, 24, 2, 'Dubai: Morning at Leisure; Evening Dhow Cruise with Dinner', 'Enjoy breakfast at the hotel.\n\nIn the evening get ready to experience the Dhow Cruise. Cruising down Dubai creek is a novel experience, one which you cannot miss when in Dubai. Having fancy dinner on a Dhow Cruise with the fascinating lights of Dubai Creek and the soft music in the background, sip your favorite drink and enjoy a buffet dinner on board the cruise.', 'Dubai', '', NULL),
(104, 24, 3, 'Dubai Half Day City Tour  Followed By At the Top Burj Khalifa', 'After breakfast, proceed for a half day morning city tour, viewing some of the city most beautiful landmarks. The Magnificent Jumeriah Mosque built in 1979 is a fine example of modern Islamic architecture.\n\nYouï¿½ll be dropped back to Dubai Mall. You can use this time to have your lunch\n\nTake a closer look at the world below through avant-garde, high powered, telescopes. Step out onto the world\'s highest public outdoor observation terrace overlooking the ever growing skyline of Sheikh Zayed Road and surrounding panorama.\n\nReturn to hotel for a comfortable overnight stay.', 'Dubai', '', NULL),
(105, 24, 4, 'Dubai-Abu Dhabi City Tour with a visit to Sheikh Zayed  Grand  Mosque', 'After breakfast, check out from your hotel in Dubai and proceed towards Abu Dhabi. \n\nAbu Dhabi, the capital of the UAE, is a gem to discover.\n\nProceed for an Abu Dhabi city tour, Abu Dhabi is the largest of the seven Emirates. Explore the majesty of the Sheikh Zayed Grand Mosque.\nVisit Ferrari World or Yas Waterworld, Yas Waterworld, Warner Bros Park. After spending time at the park return to hotel for a comfortable overnight stay. ', 'Abu Dhabi', '', NULL),
(106, 24, 5, 'Dubai Departure', 'Today enjoy breakfast at the hotel. Later check out and Transfer to Dubai airport for your departure flight. We hope you take back many happy memories of your holiday.', 'Tour End', '', NULL),
(107, 25, 1, 'Arrive Paro by Air & transfer to Thimphu', 'On arrival at Paro Airport. After immigration formalities and baggage collection, you will be met by our representative and afterwards drive to Thimphu, the capital town of Bhutan with en-route stop at Chuzom, the confluence of Thimphu and Paro rivers.', 'Thimphu', '', NULL),
(108, 25, 2, 'Thimpu', 'In the morning, visit handmade paper mill, School of Arts and crafts where students learn 13 different arts used predominantly in Bhutan. Later Simply Bhutan museum.', 'Thimphu', '', NULL),
(109, 25, 3, 'Thimphu-Punakha', 'Today\'s drive passes through Dochula pass making the most beautiful pass in Bhutan. 108 Druk Wangyel Chortens, built over the pass by queen mother in 2003 marks the pass more important than another passes. When the weather permits one can enjoy a spectacular view of the highest mountains of Bhutan at a site that stretches almost 180 degrees. After a photo break, we will continue our drive to warm valley of Punakha.', 'Punakha', '', NULL),
(110, 25, 4, 'Depart Paro', 'After early breakfast at the hotel, drive to the airport for flight to your onward destination. Our representative will help you with exit formalities and then bid you farewell.', 'Tour End', '', NULL),
(111, 26, 1, 'Arrive Paro by Air & transfer to Thimphu', 'On arrival at Paro Airport. After immigration formalities and baggage collection, you will be met by our representative and afterwards drive to Thimphu, the capital town of Bhutan with en-route stop at Chuzom, the confluence of Thimphu and Paro rivers.', 'Thimphu', '', NULL),
(112, 26, 2, 'Thimpu', 'In the morning, visit handmade paper mill, School of Arts and crafts where students learn 13 different arts used predominantly in Bhutan. Later Simply Bhutan museum.', 'Thimphu', '', NULL),
(113, 26, 3, 'Thimphu-Punakha', 'Today\'s drive passes through Dochula pass making the most beautiful pass in Bhutan. 108 Druk Wangyel Chortens, built over the pass by queen mother in 2003 marks the pass more important than another passes. When the weather permits one can enjoy a spectacular view of the highest mountains of Bhutan at a site that stretches almost 180 degrees. After a photo break, we will continue our drive to warm valley of Punakha.', 'Punakha', '', NULL),
(114, 26, 4, 'Punakha & Wangdue ï¿½ Paro', 'After breakfast drive back to Paro descending back down from Dochu La, follow the way back up the dramatic Wang Chhu and Paro Chhu river valleys, before crossing through Paro town towards the north end of the valley.\n\nLater in the day after checking into hotel, proceed to visit Ta Dzong, originally built as Watchtower, which now houses National Museum.\n\nThen walk down the trail to visit Rinpung Dzong, meaning, which has a long and fascinating history.\n\nLater in the afternoon experience Traditional Bhutanese hot stone bath.\n\nAlso, medicinal herbs are added to the water before it is ready for the soak.', 'Paro', '', NULL),
(115, 26, 5, 'Depart Paro', 'After early breakfast at the hotel, drive to the airport for flight to your onward destination. Our representative will help you with exit formalities and then bid you farewell.', 'Tour End', '', NULL),
(116, 27, 1, 'Arrive at Muscat international Airport. ', 'Arrive at Muscat international Airport. After Immigration clearance, baggage collection & customs proceed to the arrival hall to meet the representative and proceed to the Hotel.', 'Muscat', '', NULL),
(117, 27, 2, 'HALF DAY MUSCAT CITY TOUR', 'After breakfast, pick-up from the hotel and proceed to visit the Grand Mosque (not possible on Friday & other public holidays), highlight of the Muscat city.\n\nProceed to visit Bait Al Zubair Museum to have a glimpse of Omans history.\n\nProceed back to the Hotel.', 'Muscat', '', NULL),
(118, 27, 3, 'DOLPHIN WATCHING TOUR', 'Breakfast at the hotel\n\nTransfer from the Muscat hotel to the Marina to embark on a boat as we search the seas for Dolphins and Whales.\n\nReturn to the Marina and proceed back to the hotel. Rest of the day at leisure on your own to explore the city or enjoy hotel facilities.', 'Muscat', '', NULL),
(119, 27, 4, 'DEPARTURE', 'Breakfast at the hotel\n\nCheck out of the hotel and transfer to Muscat International Airport to catch flight back home.', 'Tour End', '', NULL),
(120, 28, 1, 'Arrive at Muscat international Airport. ', 'Arrive at Muscat international Airport. After Immigration clearance, baggage collection & customs proceed to the arrival hall to meet the representative and proceed to the Hotel.', 'Muscat', '', NULL),
(121, 28, 2, 'HALF DAY MUSCAT CITY TOUR', 'After breakfast, pick-up from the hotel and proceed to visit the Grand Mosque (not possible on Friday & other public holidays), highlight of the Muscat city.\n\nProceed to visit Bait Al Zubair Museum to have a glimpse of Omans history.\n\nProceed back to the Hotel.', 'Muscat', '', NULL),
(122, 28, 3, 'DOLPHIN WATCHING TOUR', 'Breakfast at the hotel\n\nTransfer from the Muscat hotel to the Marina to embark on a boat as we search the seas for Dolphins and Whales.\n\nReturn to the Marina and proceed back to the hotel. Rest of the day at leisure on your own to explore the city or enjoy hotel facilities.', 'Muscat', '', NULL),
(123, 28, 4, 'MUSCAT-NIZWA-JABAL AKHDAR', 'Breakfast at the hotel\n\nProceed to Nizwa, capital of the interior, is the birthplace of Islam in the Sultanate of Oman.\n\nEnjoy the cool climate up in the mountains.', 'Jabal Akhdar', '', NULL),
(124, 28, 5, 'DEPARTURE', 'Breakfast at the hotel\n\nCheck out of the hotel and transfer to Muscat International Airport to catch flight back home.', 'Tour End', '', NULL),
(136, 3, 5, 'd', 'd', 'Tour End', 'Dinner', NULL),
(137, 29, 1, 'Jaipur arrival', 'Arrive in Jaipur. Proceed to enjoy a half day sightseeing tour of Jaipur. Visit the City palace and local market etc', 'Jaipur', 'Breakfast', 'https://itoursdemo.co.in/uploads/itinerary_images/20251226_075831_e84ecae1_Day1.webp'),
(138, 29, 2, 'Mount Abu City Tour', 'After breakfast full day city tour includes Dilwara temple, The sun set point, Prajapita Bramhakumari Ashram and University-\'The impartation of Spiritual knowledge and meditation and picturesque Nakki Lake', 'Mount Abu', 'Breakfast', 'https://itoursdemo.co.in/uploads/itinerary_images/20251226_075831_cb8dde6d_Day3.webp'),
(139, 29, 3, 'Travel Jaisalmer to Jodhpur', 'After an early breakfast, proceed to Jodhpur. Upon arrival check in at the hotel. In the afternoon enjoy Jodhpur sightseeing. Visiting the best preserved fort of Rajasthan -the Mehrangarh fort. Later see the marble cenotaph at Jaswant Thada.', 'Jodhpur', 'Breakfast', 'https://itoursdemo.co.in/uploads/itinerary_images/20251226_075832_8b0983fb_Day12.webp'),
(140, 29, 4, 'Jodhpur Local sightseeing', 'After breakfast leave for Jodhpur local-Jodhpur-the stronghold of the fierce Rathore clan, was founded in 1459 by Prince Jodha. Visit the Mehrangarh Fort, situated on a low sandstone hill. Within the fort, visit Moti Mahal and Phool Mahal and Umaid Bhavan Palace.', 'Jodhpur', 'Breakfast', 'https://itoursdemo.co.in/uploads/itinerary_images/20251226_075832_da42321b_Day13.webp'),
(141, 29, 5, 'Day-14 Jodhpur Ajmer/Pushkar', 'After breakfast checkout from the hotel and visit Umaid Bhawan Palace and vintage car museum. Then proceed to Pushkar. Upon arrival check in at hotel. In the afternoon enjoy the sightseeing of Pushkar visiting Lord Bramha Temple, Holy Lake Pushkar and thr local colourful market.', 'Pushkar', 'Breakfast', 'https://itoursdemo.co.in/uploads/itinerary_images/20251226_075833_d4d8042a_Day14.webp'),
(142, 29, 6, 'Day-15 Pushkar Jodhpur Departure', 'After breakfast checkout from the hotel and visit the Ana sagar lake and Dargah. Later transfer to railway station / Airport at Jaipur for your onwards destination. Return home with eternal memories of you tour with Mango Holidays!', 'Tour End', 'Breakfast', 'https://itoursdemo.co.in/uploads/itinerary_images/20251226_075833_c942112c_Day15.webp'),
(180, 30, 1, 'Jaipur arrival', 'Arrive in Jaipur. Proceed to enjoy a half day sightseeing tour of Jaipur. Visit the City palace and local market etc', 'Jaipur', '', 'https://itoursdemo.co.in/uploads/itinerary_images/20251226_075831_e84ecae1_Day1.webp'),
(181, 30, 2, 'Arrival Mount Abu', 'Arrive at Mt.Abu Road station,Enjoy the unique experience of Sunset.', 'Mount Abu', '', 'https://itoursdemo.co.in/uploads/itinerary_images/20251226_075831_62864d9a_Day2.webp'),
(182, 30, 3, 'Mount Abu City Tour', 'After breakfast full day city tour includes Dilwara temple, The sun set point, Prajapita Bramhakumari Ashram and University-\'The impartation of Spiritual knowledge and meditation and picturesque Nakki Lake', 'Mount Abu', '', 'https://itoursdemo.co.in/uploads/itinerary_images/20251226_075831_cb8dde6d_Day3.webp'),
(183, 30, 4, 'Jaipur city sightseeing', 'Today after breakfast enjoy a full day sightseeing tour of Jaipur. Visit Amer Fort, Hawa Mahal, Jantar Mantar, City Palace, Museum, Govinddev Temple and Jalmahal.', 'Jaipur', '', 'https://itoursdemo.co.in/uploads/itinerary_images/20251226_075832_3937db55_Day8.webp'),
(184, 30, 5, 'Jodhpur Local sightseeing', 'After breakfast leave for Jodhpur local-Jodhpur-the stronghold of the fierce Rathore clan, was founded in 1459 by Prince Jodha. Visit the Mehrangarh Fort, situated on a low sandstone hill. Within the fort, visit Moti Mahal and Phool Mahal and Umaid Bhavan Palace.', 'Jodhpur', '', 'https://itoursdemo.co.in/uploads/itinerary_images/20251226_075832_da42321b_Day13.webp'),
(185, 30, 6, 'Day-14 Jodhpur Ajmer/Pushkar', 'After breakfast checkout from the hotel and visit Umaid Bhawan Palace and vintage car museum. Then proceed to Pushkar. Upon arrival check in at hotel. In the afternoon enjoy the sightseeing of Pushkar visiting Lord Bramha Temple, Holy Lake Pushkar and thr local colourful market.', 'Pushkar', '', 'https://itoursdemo.co.in/uploads/itinerary_images/20251226_075833_d4d8042a_Day14.webp'),
(187, 31, 1, 'On arrival in Dubai Airport', 'On arrival in Dubai check-in to your hotel. Later Proceed to Dubai Marina Cruise it is a sight to behold and cruising through the canal beside it promises unparalleled views of the buildings that have become landmarks on the international map. Among the many sights you will pass by, some that you should not miss are the Burj Al Arab, Hotel Atlantis the Palm, Palm Jumeirah, Dubai Marina Yatch Club Promenade, and the Dubai Marina Mall. You will also get a chance to admire the unique architecture that surrounds the area in form of residential buildings, recreational spaces, and office buildings in evening or in night-time cruise you can see New Dubai glittering under the dark sky. Enjoy Marina Dhow Cruise with delicious dinner.', 'Dubai', '', 'https://itoursdemo.co.in/uploads/itinerary_images/20251229_094918_f3684f57_Day-1.webp'),
(188, 31, 2, 'Half Day Dubai City Tour & Desert Safari with BBQ Dinner', 'Today after breakfast you will get an opportunity to get acquainted with Dubai city Tour Visit to Dubais famous landmarks such as the sail-shaped Burj Al-Arab hotel and beautiful Jumeirah Mosque, and learn interesting details about each attraction from a local guide. Take in views of the citys most picturesque palaces and residential areas, and venture into Bastakiya, Dubais inspiring old quarter. Cross Dubai Creek by abra (water taxi) and visit the Spice Soul. Vening Enjoy Desert Safari with BBQ Dinner & Belly Dancing.', 'Dubai', '', 'https://itoursdemo.co.in/uploads/itinerary_images/20251229_094918_457607b9_Day-2.webp'),
(189, 31, 3, 'Dubai Frame & Dhow Cruise Dinner', 'Visit Dubai Frame - known as the biggest picture frame on the planet. Later in the evening we will embark on the Dhow Dinner Cruise- enjoy amazing view of the Dubai skyline.', 'Dubai', '', 'https://itoursdemo.co.in/uploads/itinerary_images/20251229_094918_577b6801_Day-3.webp'),
(190, 31, 4, 'Miracle Garden, Desert Safari with Belly dance show', 'Today we visit Miracle Garden (if operational) -This is the largest natural flower garden in the world. After that we enjoy thrilling Desert Safari by four wheeled drive Land Cruiser through Sand dunes followed by amazing Belly Dance show along with Dinner.', 'Dubai', '', 'https://itoursdemo.co.in/uploads/itinerary_images/20251229_094918_0cce145a_Day-4.webp'),
(191, 31, 5, 'Dubai Aquarium-Underwater Zoo-Burj Khalifa', 'Today morning after breakfast proceed for Dubai mall and be part of the mesmerizing Dubai Aquarium & Underwater Zoo, it offers fascinating insight into the worlds most mysterious marine life. Later in the evening proceed to visit the Burj Khalifa Described as both a \'Vertical City\' and \'A Living Wonder\', Burj Khalifa, developed by Dubai-based Emaar Properties PJSC, is the world\'s tallest building. Later enjoy the musical fountain show.', 'Dubai', '', 'https://itoursdemo.co.in/uploads/itinerary_images/20251229_094919_ac66e1fa_Day-5.webp'),
(192, 31, 6, 'Abu Dhabi City tour-Ferrari World', 'Today after breakfast proceed for Abu Dhabi city tour with Ferrari world , the leading seasonal cultural extravaganza in the region and one of the best things to do in Dubai each time you visit.', 'Dubai', '', 'https://itoursdemo.co.in/uploads/itinerary_images/20251229_094919_c0a85bde_Day-6.webp'),
(193, 32, 1, 'Jaipur arrival', 'Arrive in Jaipur. Proceed to enjoy a half day sightseeing tour of Jaipur. Visit the City palace and local market etc', 'Jaipur', '', 'https://itoursdemo.co.in/uploads/itinerary_images/20251226_075831_e84ecae1_Day1.webp'),
(194, 32, 2, 'Arrival Mount Abu', 'Arrive at Mt.Abu Road station,Enjoy the unique experience of Sunset.', 'Mount Abu', '', 'https://itoursdemo.co.in/uploads/itinerary_images/20251226_075831_62864d9a_Day2.webp'),
(195, 32, 3, 'Mount Abu City Tour', 'After breakfast full day city tour includes Dilwara temple, The sun set point, Prajapita Bramhakumari Ashram and University-\'The impartation of Spiritual knowledge and meditation and picturesque Nakki Lake', 'Mount Abu', '', 'https://itoursdemo.co.in/uploads/itinerary_images/20251226_075831_cb8dde6d_Day3.webp'),
(196, 32, 4, 'Travel Mount Abu to Udaipur', 'After breakfas, drive toward the Udaipur on the way Visit to famous jain temples of Ranakpur, later visit haldighati maharana pratap museum.', 'Udaipur', '', 'https://itoursdemo.co.in/uploads/itinerary_images/20251226_075831_7c107563_Day4.webp'),
(197, 32, 5, 'Udaipur local sightseeing', 'After breakfast,Later start to city sight seeing tour of Udaipur.Visit the City Palace museum, Saheliyo ko badi, Bhartiya Lok Kala Mandir ( Folk art museum) and the Pratap Memorial. Rest of the day at leisure.', 'Udaipur', '', 'https://itoursdemo.co.in/uploads/itinerary_images/20251226_075831_5cbd8334_Day5.webp'),
(198, 32, 6, 'Travel Udaipur-Chittorgarh-Ajmer-Pushkar', 'After breakfast, drive toward to Ajmer and Enroute visit Chittorgarh Fort -Ranakumbha, Meera mandir, Vijay stambha and Padmini\'s palace. Arrive at Ajmer and visit Dargah Shariff, at Ajmer.', 'Pushkar', '', 'https://itoursdemo.co.in/uploads/itinerary_images/20251226_075832_e42a0201_Day6.webp'),
(199, 33, 1, 'Jaipur arrival', 'Arrive in Jaipur. Proceed to enjoy a half day sightseeing tour of Jaipur. Visit the City palace and local market etc', 'Jaipur', '', 'https://itoursdemo.co.in/uploads/itinerary_images/20251226_075831_e84ecae1_Day1.webp'),
(200, 33, 2, 'Travel Mount Abu to Udaipur', 'After breakfas, drive toward the Udaipur on the way Visit to famous jain temples of Ranakpur, later visit haldighati maharana pratap museum.', 'Udaipur', '', 'https://itoursdemo.co.in/uploads/itinerary_images/20251226_075831_7c107563_Day4.webp'),
