INSERT INTO `group_tour_program` (`entry_id`, `tour_id`, `attraction`, `day_wise_program`, `stay`, `meal_plan`, `daywise_images`) VALUES
(1, 1, 'Jaipur arrival', 'Arrive in Jaipur. Proceed to enjoy a half day sightseeing tour of <b>Jaipur</b>. Visit the City palace and local market etc<b></b><b></b><b></b>', 'Jaipur', '', ''),
(2, 1, 'Jodhpur Local sightseeing', 'After breakfast leave for <b>Jodhpur </b>local-Jodhpur-the stronghold of the fierce Rathore clan, was founded in 1459 by Prince Jodha. Visit<b> the Mehrangarh Fort</b>, situated on a low sandstone hill. Within the fort, visit Moti Mahal and Phool Mahal and Umaid Bhavan Palace.<b></b><b></b><b></b><b></b><b></b><b></b>', 'Jodhpur', '', ''),
(3, 1, 'Day-14 Jodhpur Ajmer/Pushkar', 'After breakfast checkout from the hotel and visit <b>Umaid Bhawan Palace</b> and vintage car museum. Then proceed to <b>Pushkar</b>. Upon arrival check in at hotel. In the afternoon enjoy the sightseeing of Pushkar visiting <b>Lord Bramha Temple</b>, Holy Lake Pushkar and thr local colourful market.<b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b>', 'Pushkar', '', ''),
(4, 1, 'Day-15 Pushkar Jodhpur Departure', 'After breakfast checkout from the hotel and visit the <b>Ana sagar lake</b> and <b>Dargah</b>. Later transfer to railway station / Airport at Jaipur for your onwards destination. Return home with eternal memories of you tour with Mango Holidays!<b></b><b></b><b></b><b></b><b></b><b></b>', 'Tour End', '', ''),
(5, 2, 'On arrival in Dubai Airport', 'On arrival in Dubai check-in to your hotel. Later Proceed to <b>Dubai Marina Cruise</b> it is a sight to behold and cruising through the canal beside it promises unparalleled views of the buildings that have become landmarks on the international map. Among the many sights you will pass by, some that you should not miss are the Burj Al Arab, Hotel Atlantis the Palm, Palm Jumeirah, Dubai Marina Yatch Club Promenade, and the Dubai Marina Mall. You will also get a chance to admire the unique architecture that surrounds the area in form of residential buildings, recreational spaces, and office buildings in evening or in night-time cruise you can see New Dubai glittering under the dark sky. Enjoy <b>Marina Dhow Cruise </b>with delicious dinner.<b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b>', 'Dubai', '', 'https://itourscloud.com/destination_gallery/asia/flight-landing.jpg'),
(6, 2, 'Half Day Dubai City Tour & Desert Safari with BBQ Dinner', 'Today after breakfast you will get an opportunity to get acquainted with Dubai city Tour Visit to Dubais famous landmarks such as the sail-shaped <b>Burj Al-Arab </b>hotel and beautiful Jumeirah Mosque, and learn interesting details about each attraction from a local guide. Take in views of the citys most picturesque palaces and residential areas, and venture into<b> Bastakiya</b>, Dubais inspiring old quarter. Cross Dubai Creek by abra (water taxi) and visit the Spice Soul. Vening<b> Enjoy Desert Safari with BBQ Dinner & Belly Dancing</b>.<b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b>', 'Dubai', '', 'https://itourscloud.com/destination_gallery/asia/uae/Asia_UAE_ABU_DHABI_Emirates_Palace.jpg'),
(7, 2, 'Dubai Frame & Dhow Cruise Dinner', 'Visit <b>Dubai Frame</b> - known as the biggest picture frame on the planet. Later in the evening we will embark on the <b>Dhow Dinner Cruise</b>- enjoy amazing view of the Dubai skyline.<b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b>', 'Dubai', '', 'https://itourscloud.com/destination_gallery/asia/uae/Asia_UAE_ABU_DHABI_Moreeb_Dune.jpg'),
(8, 2, 'Miracle Garden, Desert Safari with Belly dance show', 'Today we visit <b>Miracle Garden</b> (if operational) -This is the largest natural flower garden in the world. After that we enjoy thrilling <b>Desert Safari </b>by four wheeled drive Land Cruiser through Sand dunes followed by amazing Belly Dance show along with Dinner.<b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b>', 'Dubai', '', 'https://itourscloud.com/destination_gallery/asia/uae/Asia_UAE_ABU_DHABI_Yas_Island.jpg'),
(9, 2, 'Dubai Aquarium-Underwater Zoo-Burj Khalifa', 'Today morning after breakfast proceed for <b>Dubai mall </b>and be part of the mesmerizing <b>Dubai Aquarium & Underwater Zoo</b>, it offers fascinating insight into the worlds most mysterious marine life. Later in the evening proceed to visit the Burj Khalifa Described as both a \'Vertical City\' and \'A Living Wonder\', Burj Khalifa, developed by Dubai-based Emaar Properties PJSC, is the world\'s tallest building. Later enjoy the <b>musical fountain show</b>.<b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b>', 'Dubai', '', 'https://itourscloud.com/destination_gallery/asia/uae/Asia_UAE_Al_Ain_Al_Ain_Zoo.jpg'),
(10, 2, 'Dubai-Departure', 'After Breakfast at hotel Check out from hotel and get transferred to the airport to catch your flight back to your destination. <b>Tour End</b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b>', 'Tour Ends', '', 'https://itourscloud.com/destination_gallery/asia/flight-take-off.jpg'),
(11, 1, 'Haridwar/Rishikesh â€“ Guptkashi', '- Pickup from Haridwar or Rishikesh.\n- Drive via Devprayag and Rudraprayag.\n- Check in to the hotel. ', 'Guptkashi', 'B+L+D', 'https://itourscloud.com/destination_gallery/asia/train-arrival.jpg'),
(12, 1, 'Guptkashi â€“ Gaurikund â€“ Kedarnath', '- Early morning drive to Sonprayag and shuttle to Gaurikund.\n- Trek to Kedarnath (approximately 16â€“18 km) or take an optional helicopter.\n- Evening darshan at Kedarnath Temple.', 'Kedarnath', '', 'https://itourscloud.com/destination_gallery/asia/india/uttarakhand/Asia_India_Uttakhand_Badrinath.jpg'),
(13, 1, 'Kedarnath â€“ Guptkashi', 'Morning darshan at the temple.\nTrek back to Gaurikund. ', 'Guptkashi', 'B+L+D', 'https://itourscloud.com/destination_gallery/asia/india/uttarakhand/Asia_India_Uttakhand_Kedarnath.jpg'),
(14, 1, 'Guptkashi â€“ Rishikesh', 'Drive back to Rishikesh.\nVisit local attractions if time permits. ', 'Rishikesh', 'B+L+D', 'https://itourscloud.com/destination_gallery/asia/india/uttarakhand/Asia_India_Uttakhand_Haridwar.jpg'),
(15, 1, 'Departure', 'Haridwar/Rishikesh railway station or Dehradun airport.', 'Departure', 'Breakfast', 'https://itourscloud.com/destination_gallery/asia/train-depature.jpg'),
(16, 2, 'On arrival in Dubai Airport', 'On arrival in Dubai check-in to your hotel. Later Proceed to Dubai Marina Cruise it is a sight to behold and cruising through the canal beside it promises unparalleled views of the buildings that have become landmarks on the international map. Among the many sights you will pass by, some that you should not miss are the Burj Al Arab, Hotel Atlantis the Palm, Palm Jumeirah, Dubai Marina Yatch Club Promenade, and the Dubai Marina Mall. You will also get a chance to admire the unique architecture that surrounds the area in form of residential buildings, recreational spaces, and office buildings in evening or in night-time cruise you can see New Dubai glittering under the dark sky. Enjoy Marina Dhow Cruise with delicious dinner.', 'Dubai', 'Breakfast', 'https://itourscloud.com/destination_gallery/asia/flight-landing.jpg'),
(17, 2, 'Half Day Dubai City Tour & Desert Safari with BBQ Dinner', 'Today after breakfast you will get an opportunity to get acquainted with Dubai city Tour Visit to Dubais famous landmarks such as the sail-shaped Burj Al-Arab hotel and beautiful Jumeirah Mosque, and learn interesting details about each attraction from a local guide. Take in views of the citys most picturesque palaces and residential areas, and venture into Bastakiya, Dubais inspiring old quarter. Cross Dubai Creek by abra (water taxi) and visit the Spice Soul. vening Enjoy Desert Safari with BBQ Dinner & Belly Dancing.', 'Dubai', 'B+L+D', 'https://itourscloud.com/destination_gallery/asia/uae/Asia_UAE_ABU_DHABI_Qasr_al_Hosn.jpg'),
(18, 2, 'Dubai Frame & Dhow Cruise Dinner', 'Visit Dubai Frame - known as the biggest picture frame on the planet. Later in the evening we will embark on the Dhow Dinner Cruise- enjoy amazing view of the Dubai skyline.', 'Dubai', 'B+L+D', 'https://itourscloud.com/destination_gallery/asia/uae/Asia_UAE_ABU_DHABI_Yas_Island.jpg'),
(19, 2, 'Miracle Garden, Desert Safari with Belly dance show', 'Today we visit Miracle Garden (if operational) -This is the largest natural flower garden in the world. After that we enjoy thrilling Desert Safari by four wheeled drive Land Cruiser through Sand dunes followed by amazing Belly Dance show along with Dinner.', 'Dubai', 'B+L+D', 'https://itourscloud.com/destination_gallery/asia/uae/Asia_UAE_ABU_DHABI_Moreeb_Dune.jpg'),
(20, 2, 'Abu Dhabi City tour-Ferrari World', 'Today after breakfast proceed for Abu Dhabi city tour with Ferrari world , the leading seasonal cultural extravaganza in the region and one of the best things to do in Dubai each time you visit.', 'Dubai', 'B+L+D', 'https://itourscloud.com/destination_gallery/asia/uae/Asia_UAE_ABU_DHABI_Yas_Marina_Circuit.jpg'),
(21, 2, 'Dubai-Departure', 'After Breakfast at hotel Check out from hotel and get transferred to the airport to catch your flight back to your destination.Tour End', 'Tour Ends', 'Breakfast', 'https://itourscloud.com/destination_gallery/asia/flight-take-off.jpg');
