INSERT INTO `package_quotation_program` (`id`, `quotation_id`, `package_id`, `attraction`, `day_wise_program`, `stay`, `meal_plan`, `day_image`, `day_count`) VALUES
(7, 2, 29, 'On arrival in Dubai Airport', 'On arrival in Dubai check-in to your hotel. Later Proceed to <b>Dubai Marina Cruise</b> it is a sight to behold and cruising through the canal beside it promises unparalleled views of the buildings that have become landmarks on the international map. Among the many sights you will pass by, some that you should not miss are the Burj Al Arab, Hotel Atlantis the Palm, Palm Jumeirah, Dubai Marina Yatch Club Promenade, and the Dubai Marina Mall. You will also get a chance to admire the unique architecture that surrounds the area in form of residential buildings, recreational spaces, and office buildings in evening or in night-time cruise you can see New Dubai glittering under the dark sky. Enjoy <b>Marina Dhow Cruise </b>with delicious dinner.<b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b>', 'Dubai', 'Breakfast', 'https://itoursdemo.co.in/uploads/itinerary_images/20251229_094918_f3684f57_Day-1.webp', 1),
(8, 2, 29, 'Half Day Dubai City Tour & Desert Safari with BBQ Dinner', 'Today after breakfast you will get an opportunity to get acquainted with Dubai city Tour Visit to Dubais famous landmarks such as the sail-shaped <b>Burj Al-Arab </b>hotel and beautiful Jumeirah Mosque, and learn interesting details about each attraction from a local guide. Take in views of the citys most picturesque palaces and residential areas, and venture into<b> Bastakiya</b>, Dubais inspiring old quarter. Cross Dubai Creek by abra (water taxi) and visit the Spice Soul. Vening<b> Enjoy Desert Safari with BBQ Dinner & Belly Dancing</b>.<b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b>', 'Dubai', 'Breakfast', 'https://itoursdemo.co.in/uploads/itinerary_images/20251229_094918_457607b9_Day-2.webp', 2),
(9, 2, 29, 'Dubai Frame & Dhow Cruise Dinner', 'Visit <b>Dubai Frame</b> - known as the biggest picture frame on the planet. Later in the evening we will embark on the <b>Dhow Dinner Cruise</b>- enjoy amazing view of the Dubai skyline.<b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b>', 'Dubai', 'Breakfast', 'https://itoursdemo.co.in/uploads/itinerary_images/20251229_094918_577b6801_Day-3.webp', 3),
(10, 2, 29, 'Abu Dhabi City tour-Ferrari World', 'Today after breakfast proceed for <b>Abu Dhabi city tour</b> with Ferrari world , the leading seasonal cultural extravaganza in the region and one of the best things to do in Dubai each time you visit.<b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b>', 'Dubai', 'Breakfast', 'https://itoursdemo.co.in/uploads/itinerary_images/20251229_094919_c0a85bde_Day-6.webp', 4),
(11, 2, 29, 'Dubai Aquarium-Underwater Zoo-Burj Khalifa', 'Today morning after breakfast proceed for <b>Dubai mall </b>and be part of the mesmerizing <b>Dubai Aquarium & Underwater Zoo</b>, it offers fascinating insight into the worlds most mysterious marine life. Later in the evening proceed to visit the Burj Khalifa Described as both a \'Vertical City\' and \'A Living Wonder\', Burj Khalifa, developed by Dubai-based Emaar Properties PJSC, is the world\'s tallest building. Later enjoy the <b>musical fountain show</b>.<b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b>', 'Dubai', 'Breakfast', 'https://itoursdemo.co.in/uploads/itinerary_images/20251229_094919_ac66e1fa_Day-5.webp', 5),
(12, 2, 29, 'Dubai-Departure', 'After Breakfast at hotel Check out from hotel and get transferred to the airport to catch your flight back to your destination. <b>Tour End</b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b>', 'Tour Ends', 'Breakfast', 'https://itoursdemo.co.in/uploads/itinerary_images/20251229_094920_fea42b0e_Day-10.webp', 6),
