INSERT INTO `quotation_testimonial` (`testimonial_id`, `name`, `designation`, `review`, `photo`, `active_flag`, `created_at`) VALUES
(1, 'Priya Sharma', 'Family Traveler', '\"We booked our family vacation through this tour operator, and everything was perfectly organizedâ€”from hotels and sightseeing to airport transfers.', 'images/quotational_customer_testimonials/quot_testimonial_1783607731_6255.jpg', 'Active', '2026-06-30 13:38:06'),
(2, 'Rahul Mehta', 'Travel Enthusiast', '\"Planning a trip for a group of friends is never easy, but the entire experience was seamless. The itinerary was well balanced with adventure, relaxation, and nightlife.', 'images/quotational_customer_testimonials/quot_testimonial_1783607739_9132.jpg', 'Active', '2026-06-30 13:38:06'),
(3, 'Aarav & Sneha Joshi', 'Newly Married Couple', '\"Our honeymoon was absolutely magical thanks to the thoughtful planning and personalized service. Every hotel, activity, and surprise recommendation made our journey extra special.', 'images/quotational_customer_testimonials/quot_testimonial_1783607745_7625.jpg', 'Active', '2026-06-30 13:38:06'),
(4, 'Vikram Desai', 'Business Owner', '\"I\'ve traveled with many tour companies over the years, but this one stands out for its professionalism and attention to detail.', 'images/quotational_customer_testimonials/quot_testimonial_1783607753_5152.jpg', 'Active', '2026-06-30 13:38:06');
