(108, 'Japan', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '1. Passport<br>2. Photo<br>3. Air ticket<br>4. Old passport<br>5. Covering letter from applicants<br>6. Bank statement<br>7. Income tax returns<br>8. Hotel voucher<br>9. Itinerary&nbsp;<br>', 1, '', '', ''),
(109, 'Jordan', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '1. Passport<br>2. Air ticket<br>3. Photo<br>4. Old passport<br>5. Covering letter from applicant<br>6. Hotel voucher<div>7. Bank statement<br><br></div>', 1, '', '', ''),
(110, 'Kazakstan', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '1. Passport<br>2. Old passport<br>3. Photo<br>4. Air ticket<br>5. Covering letter from applicant<br>6. Bank statement<br>7. Income tax returns<br>8. Hotel voucher<br>9. Itinear&nbsp;<br>', 1, '', '', ''),
(111, 'Kenya', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '1. Passport<br>2. Photo<br>3. Air ticket<div><br></div>', 1, '', '', ''),
(112, 'Kiribati', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '<div>1. Hold a passport valid at least six months beyond the period of intended stay, with two blank visa pages</div><div>2. Hold proof of sufficient funds</div><div>3. Hold proof of onward/return airline tickets</div><div>4. Hold proof of purpose of trip</div><div>5. Hold all documents required for the next destination</div><div>6. Hold a visa for the next country, where applicable</div><div>7. Confirm with their airline that boarding will be permitted without a visa as these conditions are subject to change</div>', 1, '', '', ''),
(113, 'Korea', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '<div>1. Passport</div><div>2. Validity - Six months</div><div>3. A photocopy of duly filled visa application form</div><div>4. Two color photographs</div><div>5. Covering letter from the applicant stating the purpose and duration of the visit</div><div>6. Original confirmed return/onward air ticket</div><div>7. Proof of hotel reservation</div><div>8. Original and photocopy of Income Tax Returns and photocopy of pan card</div><div>9. Original and photocopy of Investment documents</div><div>10. All specified documents</div><div>11. Old passports and visa</div><div>12. Copy of leave letters from employer, school or college</div><div>13. Proof of accommodation during entire stay in al Schengen countries</div><div>14. Salary slip for last 6 months</div><div>15. Income tax returns for last 3 years</div><div>16. Travel insurance</div><div>17. Retirement proof/company registration proof/school college ID and copy</div>', 1, '', '', ''),
(114, 'Kosovo', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '<div>1. A completed and signed application form. Persons included in the applicantâ€™s travel document shall submit a separate application form. Minors shall submit an application form signed by a person exercising permanent or temporary parental authority or legal guardianship.</div><div>2. A recent (not older than 1 month) photograph in accordance with the international standards as set out in the International Civil Aviation Organization (ICAO) document 9303 Part 1, 6th edition.</div><div>3. A copy of your travel document. Its validity shall extend at least three months after the intended date of departure from the territory of the Republic of Kosovo. It shall contain at least two blank pages.</div><div>4. documents indicating the purpose of the journey.</div><div>5. documents in relation to accommodation, or proof of sufficient means to cover his/her accommodation;</div><div>6. documents indicating that the applicant possesses sufficient means of subsistence both for the duration of the intended stay and for the return to his country of origin or residence, or for the transit to a third country into which he is certain to be admitted, or that he is in a position to acquire such means lawfully;</div><div>7. Information enabling an assessment of the applicantâ€™s intention to leave the territory of the Republic of Kosovo before the expiry of the visa applied for.</div><div>8. Travel medical insurance valid throughout the territory of the Republic of Kosovo which covers the entire period of the personâ€™s intended stay or transit.</div><div>9. The visa fee payment of 40 EUR that applicants need to pay unless they are holders of diplomatic and official passports; children nder six (6) years old; or school children, students and teachers accompanying and visiting for studying or training purposes.</div>', 1, '', '', ''),
(115, 'Kuwait', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '1. Passport<br>2. Photo<br>3. Air ticket<br>4. Pan card', 1, '', '', ''),
(116, 'Kyrgyzstan', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '1. Passport<br>2. Photo<br>3. Air ticket<br>4. Old passport<br>5. Bank statement<br>6. Covering letter from applicant<br>7. Hotel vocuher&nbsp;', 1, '', '', ''),
(117, 'Lao Peoples Democratic Republic', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '1. Passport<br>2. Photo<br>3. Air ticket', 1, '', '', ''),
(118, 'Latvia', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '1. Passport<div>2. Old passport<br>3. Photo<br>4. Air ticket<br>5. Travel insurance&nbsp;<br>6. Bank statement</div><div>7. Income tax returns<br>8. Itinerary<br>9. Hotel voucher<br>10. Covering&nbsp; letter from applicant&nbsp;&nbsp;</div>', 1, '', '', ''),
(119, 'Lebanon', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '1. Passport<br>2. Photo<br>3. Air ticket<br>4. Old passport<br>5. Authority letter<div>6. Covering letter from applicant<br>7. Income tax returns&nbsp;<br>8. Hotel voucher&nbsp;<br>9. Bank statement&nbsp;</div>', 1, '', '', ''),
(120, 'Lesotho', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '<div>1. Passport</div><div>2. Confirmed paid Return Itinerary or Ticket</div><div>3. Invitation Letter</div><div>4. Introduction Letter</div><div>5. Bank Statement</div><div>6. Immunization Card</div><div>7. Travel Insurance</div><div>8. Other Document</div>', 1, '', '', ''),
(121, 'Liberia', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '1. Passport<br>2. Old passport<br>3. Travel insurance', 1, '', '', ''),
(122, 'Libyan Arab Jamahiriya', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '<div>1. Two completed Libya visa applications</div><div>2. Two passport type photos</div><div>3. One copy of proof of vaccination for yellow fever</div><div>4. Physical passport with 6 months validity beyond trip completion and one blank visa page</div><div>5. Non-USA passport holders must provide a copy of green card or US Visa and I-94</div><div>6. Authorization from your host that was provided by the Libya Ministry of Foreign Affairs</div><div>7. One copy of flight itinerary</div>', 1, '', '', ''),
(123, 'Liechtenstein', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '1. Passport<br>2. Old Passport<br>3. Photo<br>4. Air ticket<br>5. Travel insurance<br>6. Internal air ticket<br>7. Bank statement<br>8. Income tax returns<br>9. Itineary&nbsp;<br>&nbsp;', 1, '', '', ''),
(124, 'Lithuania', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '1. Passport<br>2. Old passport<br>3. Photo<br>4. Air ticket<br>5. Travel insurance<br>6. Bank statement<br>7. Income tax returns<br>8. Itinerary<br>9. Covering letter from applicant<br>10. Hotel voucher<br>11. NOC letter from parents/husband&nbsp;<br>', 1, '', '', ''),
(125, 'Luxembourg', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '1. Passport<br>2. Old passport<br>3. Photo<br>4. Air ticket<br>5. Travel insurance&nbsp;<br>6. Bank statement<br>7. Income tax returns&nbsp;<br>8. Itinearny<br>', 1, '', '', ''),
(126, 'Macau', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '<div>1. A completed Macau Visa Application Form;&nbsp;</div><div>2. Photocopies of the bio data page and used inside pages of a valid passport/travel document.</div><div>3. Document of financial status (e.g. bank statement, deposit in savings account, tax payment receipt, employment certificate, etc.)</div><div>4. Document of transportation to Macao and accommodation arrangement (e.g. round-trip air ticket and hotel room reservation receipts, etc.)</div><div>5. Pages carrying important information in a travel document previously used to come to Macao (if any);</div><div>6. Valid entry visa or residence visa/permit of other countries or regions (if any);</div><div>7. Recent 1.5-inch full face white background color photo.</div><div>8. Proof of purpose of visit, such as:</div><div>Leisure â€“ Tour receipt, itinerary, etc.;</div><div>Family visit â€“ Photocopy of residence/stay document of family in Macao;</div><div>Study â€“ Admission document of a higher institute in Macao;</div><div>Employment â€“ Employment approval document of Macao authorities;</div><div>Residence on dependant basis â€“ Macao identity card of family, document of kinship, etc.;</div><div>Stay as relative of non-resident worker â€“ Approval document of Macao authorities;</div>', 1, '', '', ''),
(127, 'Macedonia', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '1. Passport<br>2. Old passport<br>3. Photo<br>4. Bank statement<br>5. Travel insurance', 1, '', '', ''),
(128, 'Madagascar', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '1. Passport<br>2. Old passport<br>3. Photo<br>4. Bank statement<br>5. Air ticket<br>6. Aadhar card<br>7. Pan card<br>8. Covering letter from applicant<br>9. Hotel voucher&nbsp;', 1, '', '', ''),
(129, 'Malawi', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '1. Passport<br>2. Photo<br>3. Air ticket<br>4. Old passport<br>5. Bank statement<br>6. Itinerary<br>7. Covering letter from applicant<br>8. Hotel voucher&nbsp;&nbsp;', 1, '', '', ''),
(130, 'Malaysia', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '<div><ol><li><b>Valid Passport</b>: Your passport must be valid for at least 6 months from the date of entry.</li><li><b>Return or Onward Ticket</b>: A confirmed return or onward flight ticket within 30 days of arrival.</li><li><b>Proof of Accommodation</b>: Confirmed hotel booking or an invitation letter from a host in Malaysia.&nbsp;</li><li><b>Sufficient Funds</b>: Evidence of adequate financial means to cover your stay, such as at least USD 50 per day.</li><li><b>Malaysia Digital Arrival Card (MDAC)</b>: Complete the MDAC online at least 3 days before arrival.</li><li><b>Valid Passport</b>: With at least 6 months\' validity.</li><li><b>Recent Passport-Sized Photograph</b>: As per specifications.</li><li><b>Confirmed Flight Itinerary</b>: Including return or onward journey.</li><li><b>Proof of Accommodation</b>: Hotel bookings or invitation letter.</li><li><b>Financial Proof</b>: Bank statements or other evidence of sufficient funds.</li><li><b>Visa Application Form</b>: Duly completed and signed.</li></ol></div><div><br></div><div><div><i><b>In Additional Requirements for Indian Citizens</b></i></div><div><i style=\"box-sizing: border-box; color: rgb(33, 37, 41); font-family: system-ui, -apple-system, \" segoe=\"\" ui\",=\"\" roboto,=\"\" \"helvetica=\"\" neue\",=\"\" \"noto=\"\" sans\",=\"\" \"liberation=\"\" arial,=\"\" sans-serif,=\"\" \"apple=\"\" color=\"\" emoji\",=\"\" \"segoe=\"\" ui=\"\" symbol\",=\"\" emoji\";=\"\" font-size:=\"\" 16px;=\"\" background-color:=\"\" rgb(255,=\"\" 255,=\"\" 255);\"=\"\">If you\'re an Indian passport holder, additional documents may include:</i><br style=\"box-sizing: border-box; color: rgb(33, 37, 41); font-family: system-ui, -apple-system, \" segoe=\"\" ui\",=\"\" roboto,=\"\" \"helvetica=\"\" neue\",=\"\" \"noto=\"\" sans\",=\"\" \"liberation=\"\" arial,=\"\" sans-serif,=\"\" \"apple=\"\" color=\"\" emoji\",=\"\" \"segoe=\"\" ui=\"\" symbol\",=\"\" emoji\";=\"\" font-size:=\"\" 16px;=\"\" background-color:=\"\" rgb(255,=\"\" 255,=\"\" 255);\"=\"\"></div><div><br></div><div><ol><li><b>Valid passport</b></li><li><b>Return flight ticket (must be direct or via Singapore/Thailand)</b></li><li><b>Proof of accommodation</b></li><li><b>eNTRI registration printout</b></li><li><b>Proof of financial means</b></li></ol></div></div><div><br><br></div>', 1, '', '', ''),
(131, 'Maldives', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '<div><ol><li><b>Passport&nbsp;</b>: Must be valid for at least 1 month from the date of entry.</li><li><b>Confirmed Return/Onward Ticket</b> : Proof of travel out of Maldives within visa duration.</li><li><b>Hotel Reservation or Stay Address</b> : Proof of confirmed booking or sponsor’s address in Maldives.</li><li><b>Sufficient Funds</b> : At least USD 100 + USD 50 per day, or a credit card, or proof of sponsorship.</li><li><b>Health Declaration Form</b> : Submitted online via https://imuga.immigration.gov.mv within 96 hours before travel.</li><li><b>Visa Fee</b> : Free for first 30 days; extendable up to 90 days for a fee.</li></ol></div>', 1, '', '', ''),
(132, 'Mali', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '1. Passport<br><div>2. Photo<br>3. Air ticket<br>4. Old passport<br>5. Bank statement<br><br></div>', 1, '', '', ''),
(133, 'Malta', 'Tourist Visa', 0.00, 0.00, '30 Days', '', '', '1. Passport<br>2. Old passport<br>3. Photo<br>4. Air ticket<br>5. Travel insurance<br>6. Bank statement<br>7. Income tax returns<br>8. Balance certificate<br>9. Aadhar card<br>10. Itinerary<br>11. Covering letter from applicant<br>12. NOC letter from parents/husband', 1, '', '', ''),
